const $=s=>document.querySelector(s);let category='All products',limit=12,selected=[];try{selected=JSON.parse(localStorage.getItem('toldit-shortlist')||'[]').filter(x=>PRODUCTS.some(p=>p.id===x))}catch{}const categories=['All products',...new Set(PRODUCTS.map(p=>p.category))];const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function artwork(p){return p.image?`<img src="${p.image}" alt="${escape(p.name)} — Toldit branded concept render" loading="lazy" decoding="async">`:`<div class="placeholder"><b>TOLDIT</b><span>${escape(p.name)}</span><small>COLLECTION CONCEPT</small></div>`}
function render(){const query=$('#search').value.trim().toLowerCase();const found=PRODUCTS.filter(p=>(category==='All products'||p.category===category)&&[p.name,p.description,p.category,p.format].join(' ').toLowerCase().includes(query));$('#filters').innerHTML=categories.map(c=>`<button aria-pressed="${c===category}" class="${c===category?'active':''}" data-filter="${c}">${c}</button>`).join('');$('#results').textContent=`${found.length} ${found.length===1?'product':'products'} to explore`;$('#grid').innerHTML=found.slice(0,limit).map(p=>`<article class="card"><button data-id="${p.id}" aria-label="Explore ${escape(p.name)}"><div class="card-image">${artwork(p)}<span class="tag">IN DEVELOPMENT</span></div><div class="card-text"><small>${p.category}</small><h3>${p.name}<span aria-hidden="true">↗</span></h3><p>${p.format}</p></div></button></article>`).join('')||'<p>No products found. Try another search or category.</p>';$('#show-more').hidden=found.length<=limit;$('#count').textContent=selected.length}
function detail(id){const p=PRODUCTS.find(p=>p.id===id);$('#detail-content').innerHTML=`<div class="detail-layout"><div>${artwork(p)}</div><div><p class="eyebrow">${p.category} / IN DEVELOPMENT</p><h2>${p.name}</h2><p>${p.description}</p><p><strong>Planned format</strong><br>${p.format}</p><p class="note">Availability and pricing have not been confirmed. Images and specifications are illustrative concepts.</p><button class="button" id="add-product">${selected.includes(id)?'Remove from shortlist':'Add to shortlist + '}</button></div></div>`;$('#add-product').onclick=()=>{toggle(id);detail(id)};if(!$('#detail').open)$('#detail').showModal()}
function toggle(id){selected=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];try{localStorage.setItem('toldit-shortlist',JSON.stringify(selected))}catch{}$('#count').textContent=selected.length;listRender()}
function listRender(){$('#list-items').innerHTML=selected.length?selected.map(id=>{const p=PRODUCTS.find(p=>p.id===id);return `<div><span>${p.name}</span><button data-remove="${id}" aria-label="Remove ${escape(p.name)}">Remove</button></div>`}).join(''):'<p class="note">Your shortlist is empty. Explore the catalog to add products, or download a general partnership brief.</p>'}
function showList(){listRender();$('#shortlist').showModal()}
$('#filters').onclick=e=>{const b=e.target.closest('[data-filter]');if(b){category=b.dataset.filter;limit=12;render()}};$('#search').oninput=()=>{limit=12;render()};$('#show-more').onclick=()=>{limit+=12;render()};$('#grid').onclick=e=>{const b=e.target.closest('[data-id]');if(b)detail(Number(b.dataset.id))};document.querySelectorAll('[data-venture]').forEach(b=>b.onclick=()=>detail(PRODUCTS.find(p=>p.name===b.dataset.venture).id));document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#open-list').onclick=showList;$('#partner-list').onclick=showList;$('#list-items').onclick=e=>{const b=e.target.closest('[data-remove]');if(b)toggle(Number(b.dataset.remove))};$('#download').onclick=()=>{const lines=['TOLDIT GROUP — PRODUCT & PARTNERSHIP ENQUIRY','Prepared '+new Date().toLocaleDateString(),'Name / business: '+($('#business').value.trim()||'Not specified'),'','Products of interest:',...(selected.length?selected.map(id=>{const p=PRODUCTS.find(p=>p.id===id);return '- '+p.name+' | '+p.format}):['General partnership enquiry']),'','Notes:',$('#notes').value.trim()||'None provided','','All products are planned concepts; availability, specifications and pricing require confirmation.','This brief is prepared locally. It has not been sent and is not an order.'];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Toldit-Enquiry-Brief.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('#toast').textContent='Enquiry brief downloaded. Nothing has been sent.';$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4000)};render();
